import { Overview as InnovationHubOverview } from '../../../InnovationHub/tabs/Overview/Overview';
import { Overview as LegacyOverview } from './Overview';

export type InnovationOverviewContentProps = {
  isHubOverviewEnabled: boolean;
  dataTestId?: string;
};

export const InnovationOverviewContent = ({
  isHubOverviewEnabled,
  dataTestId,
}: InnovationOverviewContentProps) => {
  if (isHubOverviewEnabled) {
    return <InnovationHubOverview dataTestId={dataTestId} />;
  }

  return <LegacyOverview dataTestId={dataTestId} />;
};
